/* @lc app=leetcode id=2182 lang=kotlin */
class Solution { fun repeatLimitedString(s: String, repeatLimit: Int): String = IntArray(26).apply { s.forEach { set(it - 'a', get(it - 'a') + 1) } }.let { cnt -> StringBuilder().apply { intArrayOf(25).let { v -> while (v[0] >= 0) v[0] = v[0].let { i -> if (cnt[i] == 0) i - 1 else Math.min(cnt[i], repeatLimit).let { k -> repeat(k) { append('a' + i) }.also { cnt[i] = cnt[i] - k }.let { if (cnt[i] > 0) ((i - 1) downTo 0).firstOrNull { cnt[it] > 0 }?.let { j -> append('a' + j).also { cnt[j] = cnt[j] - 1 }.let { i } } ?: -1 else i - 1 } } } } }.toString() } }